---repr---
// Python `repr()` for str, and Python `str()` coercion.
//
// Mirrors CPython `Objects/unicodeobject.c:unicode_repr()` and the `str()`
// builtin. Iteration is by CODE POINT (not UTF-16 unit) so astral characters
// stay literal and unpaired surrogates (produced by argv surrogateescape
// decoding) render as `\udcff`-style escapes.

import { PyTypeError } from './errors.mjs';
import { isPrintableCodePoint, toCodePoints } from './unicode.mjs';

/**
 * Format one non-printable code point the way CPython's repr does:
 * `\xHH` for <= 0xFF, `\uHHHH` for <= 0xFFFF, `\UHHHHHHHH` otherwise.
 * Hex digits are LOWERCASE, verified against the reference binary: U+001F
 * renders as backslash-x-1-f, U+200B as backslash-u-2-0-0-b, U+E0001 as
 * backslash-U-0-0-0-e-0-0-0-1.
 */
function escapeCodePoint(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * Python `repr(s)` for a str.
 *
 * CPython chooses the quote character first: `'` normally, but `"` when the
 * string contains a `'` and no `"` (so the apostrophe needs no escaping).
 * Then, per code point: the active quote and backslash are backslash-escaped,
 * tab/newline/carriage-return get their short escapes, anything that
 * `str.isprintable()` rejects becomes a numeric escape, and everything else is
 * emitted literally.
 */
export function reprStr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  const out = [quote];
  for (const cp of toCodePoints(s)) {
    // Backslash and the active quote are the only literal escapes:
    // `\\` and e.g. `\'`. The inactive quote stays bare.
    if (cp === 0x5c /* backslash */) {
      out.push('\\\\');
    } else if (String.fromCodePoint(cp) === quote) {
      out.push('\\' + quote);
    } else if (cp === 0x09) {
      out.push('\\t');
    } else if (cp === 0x0a) {
      out.push('\\n');
    } else if (cp === 0x0d) {
      out.push('\\r');
    } else if (!isPrintableCodePoint(cp)) {
      // Covers ASCII controls and DEL (Cc), Cf/Cs/Co/Cn, Zl/Zp and the
      // non-U+0020 Zs characters -- exactly Python's isprintable() complement.
      out.push(escapeCodePoint(cp));
    } else {
      out.push(String.fromCodePoint(cp));
    }
  }
  out.push(quote);
  return out.join('');
}

/**
 * Python `str(value)` for the value kinds this program produces.
 *
 * Python ints are arbitrary precision, so they are modelled as BigInt; `str()`
 * of one is its plain decimal expansion (never a `5n` literal, never an
 * exponent). A JS number standing in for an int is widened through BigInt so
 * that e.g. 1e21 prints as `1000000000000000000000` rather than `1e+21`.
 */
export function pyStr(value) {
  if (typeof value === 'bigint') return value.toString();
  if (typeof value === 'string') return value;
  if (typeof value === 'number' && Number.isInteger(value)) {
    return BigInt(value).toString();
  }
  throw new PyTypeError(
    `pyStr() argument must be str or int, not ${typeof value}`
  );
}
---int---
// Python `int(str)` -> BigInt, a faithful port of CPython's two-stage
// conversion: `PyLong_FromUnicodeObject()` first normalises the text with
// `_PyUnicode_TransformDecimalAndSpaceToASCII()`, then hands the resulting
// ASCII buffer to `PyLong_FromString()` (base 10).

import { PyValueError } from './errors.mjs';
import { isUnicodeSpace, decimalDigitValue, toCodePoints } from './unicode.mjs';
import { reprStr } from './repr.mjs';

/** CPython's `sys.int_max_str_digits` default (PEP 7 / CVE-2020-10735 guard). */
export const DEFAULT_MAX_STR_DIGITS = 4300;

/**
 * A sentinel that `PyLong_FromString` can never accept, used exactly as
 * CPython does for code points that are neither ASCII, whitespace, nor a
 * decimal digit. Its presence guarantees the later parse fails.
 */
const SENTINEL = '\x7f';

/** `Py_ISSPACE` -- the ASCII-only space set used by `PyLong_FromString`. */
function isAsciiSpace(code) {
  return code === 0x20 || (code >= 0x09 && code <= 0x0d);
}

/**
 * Stage 1: `_PyUnicode_TransformDecimalAndSpaceToASCII`.
 *
 * Per code point: keep anything < 128 verbatim; map non-ASCII Unicode
 * White_Space to U+0020; map any non-ASCII decimal digit (category Nd) to the
 * matching ASCII digit; replace everything else with the DEL sentinel. The
 * result is always the same length in code points as the input.
 */
function transformDecimalAndSpaceToAscii(s) {
  const out = [];
  for (const cp of toCodePoints(s)) {
    if (cp < 128) {
      out.push(String.fromCharCode(cp));
      continue;
    }
    if (isUnicodeSpace(cp)) {
      out.push(' ');
      continue;
    }
    const value = decimalDigitValue(cp);
    out.push(value === null ? SENTINEL : String.fromCharCode(0x30 + value));
  }
  return out.join('');
}

/** CPython's `int()` ValueError text for a rejected literal. */
function invalidLiteral(original) {
  return new PyValueError(
    `invalid literal for int() with base 10: ${reprStr(original)}`
  );
}

/**
 * Python `int(s)` for a str argument, returning a BigInt (Python ints are
 * arbitrary precision). Throws `PyValueError` on any failure.
 */
export function pyIntFromString(s, maxStrDigits = DEFAULT_MAX_STR_DIGITS) {
  const t = transformDecimalAndSpaceToAscii(s);

  // Stage 2: `PyLong_FromString`. Leading/trailing Py_ISSPACE only -- note
  // that stage 1 has already folded non-ASCII whitespace into U+0020, which is
  // why U+3000 (ideographic space) before a digit parses while U+200B
  // (zero-width space, category Cf and therefore not White_Space) does not.
  let i = 0;
  let end = t.length;
  while (i < end && isAsciiSpace(t.charCodeAt(i))) i++;
  while (end > i && isAsciiSpace(t.charCodeAt(end - 1))) end--;

  // A single optional sign; no whitespace is permitted after it.
  let negative = false;
  if (i < end && (t[i] === '+' || t[i] === '-')) {
    negative = t[i] === '-';
    i++;
  }

  // Digits with PEP 515 underscores: `\d+(?:_\d+)*`. An underscore is legal
  // only immediately after a digit, and the run may not end on one.
  const digitsStart = i;
  let digitCount = 0;
  let afterDigit = false;
  for (; i < end; i++) {
    const code = t.charCodeAt(i);
    if (code >= 0x30 && code <= 0x39) {
      digitCount++;
      afterDigit = true;
    } else if (code === 0x5f /* _ */) {
      if (!afterDigit) throw invalidLiteral(s);
      afterDigit = false;
    } else {
      // Anything else -- including the stage-1 sentinel, '.', 'x', or
      // whitespace that is not at the very edges -- is a hard failure.
      throw invalidLiteral(s);
    }
  }
  if (digitCount === 0 || !afterDigit) throw invalidLiteral(s);

  // Stage 3: the `sys.int_max_str_digits` guard counts digit CHARACTERS --
  // sign and underscores excluded, leading zeros included -- and rejects
  // strictly more than the limit. Checked before building the BigInt so a
  // pathologically long input costs only the linear scan above.
  if (digitCount > maxStrDigits) {
    throw new PyValueError(
      `Exceeds the limit (${maxStrDigits} digits) for integer string ` +
        `conversion: value has ${digitCount} digits; use ` +
        'sys.set_int_max_str_digits() to increase the limit'
    );
  }

  const cleaned = t.slice(digitsStart, end).replace(/_/g, '');
  const magnitude = BigInt(cleaned);
  // BigInt has no negative zero, so Python's "-0" -> 0 falls out for free.
  return negative ? -magnitude : magnitude;
}

---unicode---
/**
 * Unicode character classification, limited to the queries CPython makes in this program:
 *
 *   - decimal-digit membership / value  (`Py_UNICODE_ISDIGIT` / `Py_UNICODE_TODECIMAL`,
 *     used by `_PyUnicode_TransformDecimalAndSpaceToASCII` behind `int(str)`)
 *   - whitespace membership             (`Py_UNICODE_ISSPACE`)
 *   - printability                      (`str.isprintable()`, used by `repr(str)`)
 *
 * Everything is derived from the engine's own Unicode tables via RegExp property
 * escapes, so no data tables are shipped. Node 18.19 (ICU 74.2) exposes Unicode 15.1;
 * CPython 3.12 ships Unicode 15.0. The two agree on every code point exercised here.
 */

const MAX_CODE_POINT = 0x10ffff;

// General_Category=Nd (decimal digit). Anchored + `u` so a single code point (including a
// lone surrogate) is tested as one atom.
const ND_RE = /^\p{Nd}$/u;

// Python: `str.isprintable()` is false for categories Cc, Cf, Cs, Co, Cn and Zl, Zp, Zs
// (U+0020 being the documented exception, handled in `isPrintableCodePoint`).
// `\p{Cn}` is the short name of `\p{Unassigned}`; both were verified to compile on this
// Node version, and the short form matches the category list CPython documents.
const NON_PRINTABLE_RE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

/**
 * Split a string into code points. `Array.from` uses the string iterator, which walks
 * code points and yields *lone* surrogates unchanged — required because argv decoded with
 * surrogateescape carries U+DC80..U+DCFF.
 */
export function toCodePoints(str) {
  return Array.from(str, (ch) => ch.codePointAt(0));
}

/** True when `cp` is in General_Category Nd. */
export function isDecimalDigit(cp) {
  if (!Number.isInteger(cp) || cp < 0 || cp > MAX_CODE_POINT) return false;
  return ND_RE.test(String.fromCodePoint(cp));
}

// Memoises both hits and misses (`null`); the digit scan below is comparatively costly.
const digitValueCache = new Map();

/**
 * Decimal value 0..9 of an Nd code point, or `null` for anything else
 * (CPython `Py_UNICODE_TODECIMAL`).
 */
export function decimalDigitValue(cp) {
  const cached = digitValueCache.get(cp);
  if (cached !== undefined) return cached;
  const value = computeDecimalDigitValue(cp);
  digitValueCache.set(cp, value);
  return value;
}

function computeDecimalDigitValue(cp) {
  if (!isDecimalDigit(cp)) return null;

  // Fast path: NFKC folds the *compatibility* digit blocks onto ASCII — fullwidth
  // U+FF10.., and the five mathematical blocks U+1D7CE..U+1D7FF which sit back to back
  // (a 50-code-point run) and therefore defeat the offset walk below.
  const folded = String.fromCodePoint(cp).normalize('NFKC');
  if (folded.length === 1) {
    const code = folded.charCodeAt(0);
    if (code >= 0x30 && code <= 0x39) return code - 0x30;
  }

  // Slow path: every remaining Nd block is exactly ten consecutive code points, so the
  // distance to the start of the run is the digit value. Walk down at most nine steps.
  let start = cp;
  while (cp - start < 9 && isDecimalDigit(start - 1)) start -= 1;
  const value = cp - start;
  if (value < 0 || value > 9) return null;
  // A run that keeps going past ten code points is not a plain 0..9 block; rather than
  // guess a value, report "not a decimal digit" so `int()` raises ValueError.
  if (value === 9 && isDecimalDigit(start - 1)) return null;
  return value;
}

/**
 * CPython `Py_UNICODE_ISSPACE`: the ASCII half comes from `_Py_ascii_whitespace`
 * (0x09-0x0D, 0x1C-0x1F, 0x20), the rest from Unicode White_Space.
 *
 * Note the asymmetry that 0x1C-0x1F (FS/GS/RS/US) *are* Python unicode-space here, yet
 * `int()` never strips them: `_PyUnicode_TransformDecimalAndSpaceToASCII` only maps
 * cp >= 128 spaces to ' ', and the subsequent ASCII strip covers 0x09-0x0D and 0x20 only.
 * That filtering lives in int.mjs — this predicate stays faithful to the C macro.
 */
export function isUnicodeSpace(cp) {
  if (cp >= 0x09 && cp <= 0x0d) return true; // TAB LF VT FF CR
  if (cp >= 0x1c && cp <= 0x1f) return true; // FS GS RS US
  if (cp === 0x20 || cp === 0x85 || cp === 0xa0) return true; // SPACE, NEL, NBSP
  if (cp === 0x1680) return true; // OGHAM SPACE MARK
  if (cp >= 0x2000 && cp <= 0x200a) return true; // EN QUAD .. HAIR SPACE
  if (cp === 0x2028 || cp === 0x2029) return true; // LINE / PARAGRAPH SEPARATOR
  if (cp === 0x202f || cp === 0x205f) return true; // NARROW NBSP, MEDIUM MATH SPACE
  return cp === 0x3000; // IDEOGRAPHIC SPACE
}

/** Python `str.isprintable()` applied to a single code point. */
export function isPrintableCodePoint(cp) {
  // Python treats U+0020 as printable even though it is Zs; every other separator and
  // every C* code point is not.
  if (cp === 0x20) return true;
  if (!Number.isInteger(cp) || cp < 0 || cp > MAX_CODE_POINT) return false;
  return !NON_PRINTABLE_RE.test(String.fromCodePoint(cp));
}
---errors---
/**
 * Python-shaped exception objects.
 *
 * CPython identifies an exception by its *type name*: `type(exc).__name__` is what
 * tracebacks show and what code such as argparse's `except (TypeError, ValueError)`
 * reasons about. To make both `err.name` and `err.constructor.name` read exactly like
 * the CPython name, each class is declared as a *named class expression* whose inner
 * name is the Python name ('Exception', 'ValueError', 'TypeError') while the exported
 * binding keeps the `Py`-prefixed name required by the module contract. Declaring them
 * this way also avoids shadowing the JS globals `TypeError` inside this module.
 */

/** Python `Exception`: the base of the (tiny) hierarchy this port needs. */
export const PyException = class Exception extends Error {
  constructor(message = '') {
    super(message);
    // `new.target` is the most-derived constructor, so subclasses inherit this line
    // and still report their own Python name (mirrors `type(exc).__name__`).
    this.name = new.target.name;
  }
};

/** Python `ValueError` — raised by `int(str)` on a malformed literal. */
export const PyValueError = class ValueError extends PyException {};

/** Python `TypeError` — the other exception argparse catches around `type()` calls. */
export const PyTypeError = class TypeError extends PyException {};

