// Enumerate all Nd runs (contiguous code point ranges) using the engine tables.
const nd = [];
for (let cp = 0; cp <= 0x10ffff; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  if (/^\p{Nd}$/u.test(String.fromCodePoint(cp))) nd.push(cp);
}
const runs = [];
for (const cp of nd) {
  const last = runs[runs.length - 1];
  if (last && cp === last[1] + 1) last[1] = cp; else runs.push([cp, cp]);
}
console.log('total Nd code points:', nd.length, 'runs:', runs.length);
for (const [a, b] of runs) {
  const len = b - a + 1;
  if (len !== 10) console.log('NON-10 RUN', a.toString(16), b.toString(16), 'len', len);
}
// blocks of exactly ten, each aligned so a is the zero digit
const bad = runs.filter(([a,b]) => (b-a+1) % 10 !== 0);
console.log('runs not multiple of 10:', JSON.stringify(bad.map(([a,b])=>[a.toString(16),b.toString(16)])));
EOF
