// Emit "label<TAB>value" lines for the digit-block differential tests.
const nd = [];
for (let cp = 0; cp <= 0x10ffff; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  if (/^\p{Nd}$/u.test(String.fromCodePoint(cp))) nd.push(cp);
}
const lines = [];
let all = '';
for (let i = 0; i < nd.length; i += 10) {
  const block = nd.slice(i, i + 10);
  const s = block.map((c) => String.fromCodePoint(c)).join('');
  lines.push(`ndblock+${block[0].toString(16)}\t${s}`);
