  lines.push(`ndmix+${block[0].toString(16)}\t1${String.fromCodePoint(block[3])}9`);
  lines.push(`ndunder+${block[0].toString(16)}\t${String.fromCodePoint(block[1])}_${String.fromCodePoint(block[2])}`);
  lines.push(`ndneg+${block[0].toString(16)}\t-${String.fromCodePoint(block[5])}`);
}
lines.push(`nd-all-680\t${all}`);
