const esc = (s) => Array.from(enc.encode(s), (b) => '\\x' + b.toString(16).padStart(2, '0')).join('');
const out = [];
const add = (label, s) => out.push(label + '\t' + esc(s));

// cp >= 128 Unicode White_Space (folded to U+0020 by stage 1) + the ASCII space set
const spaces = [0x85, 0xa0, 0x1680, 0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005, 0x2006,
                0x2007, 0x2008, 0x2009, 0x200a, 0x2028, 0x2029, 0x202f, 0x205f, 0x3000,
                0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20];
