  const w = String.fromCodePoint(cp);
  const h = 'U+' + cp.toString(16);
  add(`ws-lead ${h}`, w + '5');
  add(`ws-trail ${h}`, '5' + w);
  add(`ws-both ${h}`, w + w + '5' + w);
  add(`ws-inner ${h}`, '5' + w + '5');
  add(`ws-aftersign ${h}`, '-' + w + '5');
  add(`ws-only ${h}`, w);
  add(`ws-beforesign ${h}`, w + '-5');
